<?php

/* @autogenerated */
declare(strict_types=1);

namespace {
    use PHPUnit\Framework\TestCase;
    use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
    use OpenTelemetry\Context\ContextInterface;
    use OpenTelemetry\SDK\Trace\ReadWriteSpanInterface;
    use OpenTelemetry\SDK\Trace\SpanExporterInterface;
    use OpenTelemetry\SDK\Trace\SpanProcessor\SimpleSpanProcessor;
    use Civi\Lughauth\Bootstrap\Telemetry\InjectResourceAttrsProcessor;
    use Civi\Lughauth\Shared\Context;

    /**
     * Unit tests for {@see InjectResourceAttrsProcessor} (Bootstrap\Telemetry).
     */
    #[AllowMockObjectsWithoutExpectations]
    final class BootstrapTelemetryInjectResourceAttrsProcessorUnitTest extends TestCase
    {
        /**
         * Ensures the processor extends SimpleSpanProcessor.
         */
        public function testExtendsSimpleSpanProcessor(): void
        {
            $exporter = $this->createMock(SpanExporterInterface::class);
            $context = $this->createMock(Context::class);

            $processor = new InjectResourceAttrsProcessor($exporter, $context);

            $this->assertInstanceOf(SimpleSpanProcessor::class, $processor);
        }

        /**
         * Ensures onStart injects all instance data as span attributes.
         */
        public function testOnStartInjectsContextAttributesIntoSpan(): void
        {
            $instanceData = [
                'service.name'        => 'lughauth',
                'service.namespace'   => 'auth',
                'service.version'     => '2.0.0',
                'service.instance.id' => 'node-1',
                'deployment.environment' => 'staging',
            ];

            $exporter = $this->createMock(SpanExporterInterface::class);
            $context = $this->createMock(Context::class);
            $context->method('getInstanceData')->willReturn($instanceData);

            $span = $this->createMock(ReadWriteSpanInterface::class);
            $parentCtx = $this->createMock(ContextInterface::class);

            $recorded = [];
            $span->method('setAttribute')
                ->willReturnCallback(function (string $key, mixed $value) use ($span, &$recorded): ReadWriteSpanInterface {
                    $recorded[$key] = $value;
                    return $span;
                });

            $processor = new InjectResourceAttrsProcessor($exporter, $context);
            $processor->onStart($span, $parentCtx);

            $this->assertSame($instanceData, $recorded);
        }
    }
}
